#!/usr/bin/env python3
"""PreToolUse hook for the Read tool.

Blocks reads that would return >= CHAR_THRESHOLD characters and tells
Claude to delegate the read to a subagent instead, so the huge content
never lands in the main context window.
"""

# AUTO-GENERATED by agent-tooling/hooks/build/build.py. Do not edit.

import os
import subprocess
from pathlib import Path
import json
import time
import uuid
from datetime import datetime
import sys


# --- inlined from adapters/claude/common/dotenv.py ---
def strip_quotes(value):
    """Strip surrounding whitespace and one matching pair of `"`/`'` quotes."""
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
        return value[1:-1]
    return value


def load_dotenv_value(path, key):
    """Read `key`'s value from the KEY=VALUE file at `path`.

    Returns `None` if the file doesn't exist/can't be read, or if `key` is
    never assigned in it. Blank lines, `#`-comments, and lines without `=`
    are skipped. Surrounding whitespace and a single matching pair of `"`/`'`
    quotes around the value are stripped, same as shell-style `.env` files.
    """
    try:
        with open(path, "r", encoding="utf-8") as f:
            lines = f.readlines()
    except OSError:
        return None

    found = None
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        name, _, value = line.partition("=")
        if name.strip() != key:
            continue
        found = strip_quotes(value)
    return found


# --- inlined from adapters/claude/common/paths.py ---
def hook_dir():
    """Directory holding the installed hook file (config/, .env, state/, logs/)."""
    return Path(__file__).resolve().parent


def _git_toplevel():
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            capture_output=True,
            text=True,
            timeout=3,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    top = result.stdout.strip()
    return Path(top) if result.returncode == 0 and top else None


def resolve_project_dir(payload=None):
    """Project root: ``CLAUDE_PROJECT_DIR``, stdin ``cwd``, git top level, then cwd."""
    env_value = os.environ.get("CLAUDE_PROJECT_DIR")
    if env_value:
        return Path(env_value)
    cwd = payload.get("cwd") if isinstance(payload, dict) else None
    if isinstance(cwd, str) and cwd:
        return Path(cwd)
    return _git_toplevel() or Path.cwd()


# --- inlined from adapters/claude/common/hook_log.py ---
TRUTHY = {"1", "true", "yes", "on"}
FALSY = {"0", "false", "no", "off"}


def resolve_bool_flag(key, default):
    """Resolve a boolean on/off flag shared across hook scripts.

    `key` from the environment or the hook directory's `.env` overrides
    `default` when set to a recognized true/false value. Unrecognized or unset
    values fall back to `default`. Used for per-script toggles like `HOOK_LOG`
    (debug logging) or `NOTIFY_INJECTED_VARS` (inject_env_vars.py's
    injected-vars notification).
    """
    raw = os.environ.get(key)
    if raw is None:
        raw = load_dotenv_value(hook_dir() / ".env", key)
    if raw is None:
        return default

    normalized = raw.strip().lower()
    if normalized in TRUTHY:
        return True
    if normalized in FALSY:
        return False
    return default


def is_log_enabled(default):
    """Resolve the effective DEBUG-LOG on/off state for this invocation.

    This governs debug logging only, not whether the hook itself is active.
    """
    return resolve_bool_flag("HOOK_LOG", default)


def _uuid7_hex():
    """Time-ordered UUID (RFC 9562 UUIDv7) so log filenames sort chronologically.

    Backfills `uuid.uuid7()` (stdlib only from Python 3.14) since only the
    time-ordering property of v7 is needed here.
    """
    ts_ms = int(time.time() * 1000)
    rand_a = int.from_bytes(os.urandom(2), "big") & 0xFFF
    rand_b = int.from_bytes(os.urandom(8), "big") & ((1 << 62) - 1)
    value = (ts_ms << 80) | (0x7 << 76) | (rand_a << 64) | (0b10 << 62) | rand_b
    return str(uuid.UUID(int=value))


def write_log(script_name, record):
    """Best-effort write of `record` to its own file under logs/{script_name}/."""
    try:
        script_dir = hook_dir() / "logs" / script_name
        os.makedirs(script_dir, exist_ok=True)
        log_path = script_dir / f"{_uuid7_hex()}.log"

        record = dict(record)
        record.setdefault("timestamp", datetime.now().astimezone().isoformat())

        with open(log_path, "w", encoding="utf-8") as f:
            json.dump(record, f, ensure_ascii=False, indent=2, default=str)
    except Exception:
        pass


# --- inlined from adapters/claude/common/runtime.py ---
def configure_utf8_stdio():
    """Force UTF-8 stdio.

    Windows can default stdio to a locale codepage (e.g. cp932) instead of
    UTF-8; without this, JSON parsing and non-ASCII (e.g. Japanese) messages
    can break.
    """
    sys.stdin.reconfigure(encoding="utf-8")
    sys.stdout.reconfigure(encoding="utf-8")
    sys.stderr.reconfigure(encoding="utf-8")


def read_json_stdin(finish):
    """Read+parse a JSON payload from stdin.

    On unparsable input, calls `finish(0, reason="unparsable stdin")` --
    which is expected to exit the process (as the `finish()` closures in
    this module and every hook script do) -- so this function only returns
    on success.
    """
    try:
        return json.load(sys.stdin)
    except (json.JSONDecodeError, ValueError):
        finish(0, reason="unparsable stdin")


def make_finish(script_name, log, log_enabled):
    """Build the standard `finish(code, output=None, **extra)` closure.

    `extra` is merged into `log` before it's (optionally) written via
    `write_log()`. If `output` is given, it's printed to stdout as JSON
    (Claude Code hook output, e.g. `hookSpecificOutput`/`systemMessage`
    payloads) before the process exits with `code`.
    """

    def finish(code, output=None, **extra):
        log.update(extra)
        log["exit_code"] = code
        if log_enabled:
            write_log(script_name, log)
        if output is not None:
            print(json.dumps(output, ensure_ascii=False))
        sys.exit(code)

    return finish


def init_hook_context(script_name, enable_hook_log_default):
    """Run the full common hook-startup sequence and return its results.

    Combines `configure_utf8_stdio()`, debug-log-enabled resolution, `log`
    dict creation, `make_finish()`, and `read_json_stdin()` -- the sequence
    shared by the majority of hook scripts (see `block_large_read.py`'s
    `main()` for the minimal example this is based on). Returns
    `(payload, log, finish)`; `payload` is the parsed JSON stdin dict (this
    call never returns if stdin was unparsable, since `finish()` exits first).
    """
    configure_utf8_stdio()
    log_enabled = is_log_enabled(enable_hook_log_default)
    log = {}
    finish = make_finish(script_name, log, log_enabled)
    payload = read_json_stdin(finish)
    return payload, log, finish


def env_int(name, default):
    """Read an int-valued environment variable, falling back to `default`
    on missing/unparsable values."""
    try:
        return int(os.environ.get(name, default))
    except (TypeError, ValueError):
        return default


# --- adapters/claude/block_large_read.py ---
"""
環境変数（省略可）:
- `HOOK_LOG` このフックの「デバッグログ」（詳細ログ）を配置先ディレクトリの`logs/block_large_read/`に
             書き出すかどうか（true/false等）。フック自体の有効/無効ではない
             （そちらは登録の有無で決まる）。
             未設定ならスクリプト先頭の`ENABLE_HOOK_LOG`に従う。
             配置先ディレクトリの`.env`に設定されていればそちらが優先。
"""


# Debug-log ON/OFF only (writes to logs/block_large_read/ next to this hook) --
# NOT whether this hook itself runs (that's whether it is registered).
# HOOK_LOG in the `.env` next to this hook, if set, overrides this default.
ENABLE_HOOK_LOG = False

SCRIPT_NAME = os.path.splitext(os.path.basename(__file__))[0]

CHAR_THRESHOLD = 2000
DEFAULT_LIMIT = 2000  # matches the Read tool's own default page size (lines)


def main():
    payload, log, finish = init_hook_context(SCRIPT_NAME, ENABLE_HOOK_LOG)

    log["tool_name"] = payload.get("tool_name")
    if payload.get("tool_name") != "Read":
        finish(0, reason="not a Read call")

    tool_input = payload.get("tool_input") or {}
    log["tool_input"] = tool_input
    file_path = tool_input.get("file_path")
    if not file_path:
        finish(0, reason="no file_path in tool_input")

    try:
        with open(file_path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except OSError as e:
        finish(0, reason="OSError opening file", error=str(e))
    except Exception as e:
        finish(0, reason="unexpected error opening file", error=str(e))

    offset = tool_input.get("offset") or 0
    start = max(offset - 1, 0) if offset > 0 else 0
    limit = tool_input.get("limit") or DEFAULT_LIMIT
    selected = lines[start : start + limit]
    char_count = sum(len(line) for line in selected)
    log["char_count"] = char_count
    log["char_threshold"] = CHAR_THRESHOLD

    if char_count < CHAR_THRESHOLD:
        finish(0, reason="below threshold, passed through")

    message = (
        f"このファイル({file_path})の読み取り内容は{char_count}文字あり、"
        f"巨大な読み取り内容です。メインの会話コンテキストを圧迫するため、"
        f"直接Readするのではなく、サブエージェント(Agent tool)に読ませて"
        f"要約・該当箇所の抽出をさせてください。"
    )
    print(message, file=sys.stderr)
    finish(2, reason="blocked: over threshold", message=message)


if __name__ == "__main__":
    main()
